import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, vec3, uv } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE, primitives, fontAtlas, textureLoader } = ctx;
  const { Group, Mesh, PlaneGeometry, DirectionalLight } = THREE;

  const root = new Group();

  // ===== STAGE BACKDROP =====
  // Gradient plane: #0b0b10 (top) to #12121a (bottom)
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const c1 = vec3(11 / 255, 11 / 255, 16 / 255); // #0b0b10
  const c2 = vec3(18 / 255, 18 / 255, 26 / 255); // #12121a
  backdropMat.colorNode = mix(c1, c2, uv().y);

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  root.add(backdrop);

  // ===== CARDS GROUP (parallax parent) =====
  const cardsGroup = new Group();
  cardsGroup.rotation.y = (-18 * Math.PI) / 180;
  root.add(cardsGroup);

  // ===== TEXT: HEADLINE & BODY =====
  const headline = fontAtlas.createText('The collection', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'left',
  });
  headline.position.set(-2.6, 1.5, 0);
  root.add(headline);

  const bodyText = fontAtlas.createText('Five calibres. One discipline.', {
    fontSize: 26,
    color: '#e8ecf2',
    align: 'left',
  });
  bodyText.position.set(-2.6, -1.5, 0);
  root.add(bodyText);

  // ===== CARD SETUP =====
  const cards = [];
  const cardNames = [
    'NA-01 MERIDIAN',
    'NA-02 NOCTURNE',
    'NA-03 SIGNAL',
    'NA-04 VANTAGE',
    'NA-05 ARCHIVE',
  ];
  const cardPositions = [-2 * 1.85, -1 * 1.85, 0, 1 * 1.85, 2 * 1.85];

  // Load texture and create cards
  textureLoader.loadTexture(config.imageUrl).then((texture) => {
    cardPositions.forEach((x, i) => {
      // Bevel frame (border behind)
      const borderGeo = new PlaneGeometry(1.65, 1.05);
      const borderMat = new MeshBasicNodeMaterial({ color: 0x16161d });
      const borderMesh = new Mesh(borderGeo, borderMat);
      borderMesh.position.z = -0.01;

      // Main card plane
      const cardGeo = new PlaneGeometry(1.6, 1.0);
      const isCenterCard = i === 2;
      const cardMat = new MeshPhysicalNodeMaterial({
        transparent: true,
        roughness: 0.55,
        metalness: 0.2,
        clearcoat: 0.15,
        clearcoatRoughness: 0.1,
        map: texture,
        opacity: isCenterCard ? 1.0 : 0.55,
      });

      const cardMesh = new Mesh(cardGeo, cardMat);

      // Card container
      const card = new Group();
      card.add(borderMesh);
      card.add(cardMesh);
      card.position.x = x;
      card.userData.mesh = cardMesh;

      // Caption below card
      const caption = fontAtlas.createText(cardNames[i], {
        fontSize: 18,
        color: '#e8ecf2',
        align: 'center',
      });
      caption.position.y = -0.65;
      caption.position.z = 0.1;
      card.add(caption);

      cardsGroup.add(card);
      cards.push(card);
    });
  });

  // ===== UNDERLINE BAR (under focused card) =====
  const underlineGeo = new PlaneGeometry(1.6, 0.035);
  const underlineMat = new MeshBasicNodeMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.3,
  });
  const underlineBar = new Mesh(underlineGeo, underlineMat);
  underlineBar.position.y = -0.52;
  underlineBar.position.z = 0.1;
  cardsGroup.add(underlineBar);

  // ===== FOCUS & OPACITY UPDATE =====
  const updateCardStates = () => {
    if (cards.length === 0) return;

    // Find focused card (closest to x=0 in world space)
    let focusedIndex = 0;
    let minDist = Infinity;

    cards.forEach((card, i) => {
      const worldX = cardsGroup.position.x + card.position.x;
      const dist = Math.abs(worldX);
      if (dist < minDist) {
        minDist = dist;
        focusedIndex = i;
      }
    });

    // Update card states
    cards.forEach((card, i) => {
      const worldX = cardsGroup.position.x + card.position.x;
      const distance = Math.abs(worldX);

      if (i === focusedIndex) {
        // Focused: counter-rotate, scale 1.0, opacity 1.0
        card.rotation.y = -cardsGroup.rotation.y;
        card.scale.set(1.0, 1.0, 1.0);
        card.userData.mesh.material.opacity = 1.0;
        underlineBar.position.x = card.position.x;
      } else {
        // Non-focused: no rotation, scale 0.92, opacity falls with distance
        card.rotation.y = 0;
        card.scale.set(0.92, 0.92, 0.92);
        const maxDist = 3.5;
        const normDist = Math.min(1, distance / maxDist);
        const opacity = Math.max(0.55, 1.0 - normDist * 0.45);
        card.userData.mesh.material.opacity = opacity;
      }
    });
  };

  gsap.ticker.add(updateCardStates);

  // ===== APPLY PARALLAX-SCROLL PRIMITIVE =====
  const parallaxResult = primitives['parallax-scroll'](cardsGroup, {
    intensity: 0.5,
  });

  // ===== ACCENT RIM LIGHT =====
  const rimLight = new DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-2, 1, 1.5);
  root.add(rimLight);

  // ===== CLEANUP =====
  root.userData.cleanup = () => {
    gsap.ticker.remove(updateCardStates);
    if (parallaxResult?.cleanup) parallaxResult.cleanup();

    cards.forEach((card) => {
      card.traverse((obj) => {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (obj.material.map) obj.material.map.dispose();
          obj.material.dispose();
        }
      });
    });

    backdrop.geometry.dispose();
    backdrop.material.dispose();
    underlineBar.geometry.dispose();
    underlineBar.material.dispose();
  };

  return root;
}
